WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='CAMBIO_DE_BOGIE' AND v.numero=1), d(titulo,orden) AS (VALUES ('BOGIE',1),('RESPONSABLES BOGIE',2),('CAJA REDUCTORA',3),('RESPONSABLES CAJA REDUCTORA',4)) INSERT INTO cartillas.secciones(version_id,titulo,orden) SELECT v.id,d.titulo,d.orden FROM v CROSS JOIN d ON CONFLICT(version_id,orden) DO UPDATE SET titulo=EXCLUDED.titulo,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;

WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='CAMBIO_DE_BOGIE' AND v.numero=1), s AS (SELECT id,titulo FROM cartillas.secciones WHERE version_id=(SELECT id FROM v)), filas AS (SELECT jsonb_agg(jsonb_build_object('serie_antes','','bogie',b,'coche',c,'eje',e,'serie_despues','') ORDER BY e) datos FROM unnest(ARRAY['PB3','PB3','PB4','PB4','PB6','PB6','PB2','PB2','PB6','PB6','PB2','PB2','TB1','TB1','TB2','TB2','PB2','PB2','PB6','PB6','PB4','PB4','PB3','PB3']) WITH ORDINALITY x(b,n) JOIN unnest(ARRAY['MA 1','MA 1','MA 1','MA 1','MB 1','MB 1','MB 1','MB 1','MB 3','MB 3','MB 3','MB 3','R','R','R','R','MB 2','MB 2','MB 2','MB 2','MA 2','MA 2','MA 2','MA 2']) WITH ORDINALITY y(c,n) USING(n) JOIN generate_series(1,24) e ON e=x.n), d(titulo,codigo,etiqueta,orden,config) AS (VALUES ('BOGIE','descripcion_bogie','Descripción:','1','{}'),('BOGIE','cambio_bogie','CAMBIO DE BOGIE','2',jsonb_build_object('columnas',jsonb_build_array(jsonb_build_object('codigo','serie_antes','etiqueta','Serie Antes'),jsonb_build_object('codigo','bogie','etiqueta','Bogie'),jsonb_build_object('codigo','coche','etiqueta','Coche'),jsonb_build_object('codigo','eje','etiqueta','Eje'),jsonb_build_object('codigo','serie_despues','etiqueta','Serie Después')),'filasIniciales',(SELECT datos FROM filas))),('CAJA REDUCTORA','descripcion_reductora','Descripción:','1','{}'),('CAJA REDUCTORA','cambio_reductora','CAMBIO DE CAJA REDUCTORA','2',jsonb_build_object('columnas',jsonb_build_array(jsonb_build_object('codigo','serie_antes','etiqueta','Serie Antes'),jsonb_build_object('codigo','bogie','etiqueta','Bogie'),jsonb_build_object('codigo','coche','etiqueta','Coche'),jsonb_build_object('codigo','eje','etiqueta','Eje'),jsonb_build_object('codigo','serie_despues','etiqueta','Serie Después')),'filasIniciales',(SELECT datos FROM filas)))) INSERT INTO cartillas.campos(seccion_id,codigo,etiqueta,tipo,orden,configuracion) SELECT s.id,d.codigo,d.etiqueta,CASE WHEN d.codigo LIKE 'cambio%' THEN 'tabla' ELSE 'texto' END,d.orden::int,d.config FROM d JOIN s ON s.titulo=d.titulo ON CONFLICT(seccion_id,codigo) DO UPDATE SET configuracion=EXCLUDED.configuracion,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;

WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='CAMBIO_DE_BOGIE' AND v.numero=1), s AS (SELECT id,titulo FROM cartillas.secciones WHERE version_id=(SELECT id FROM v)), d(titulo,codigo,etiqueta,tipo,orden) AS (VALUES ('RESPONSABLES BOGIE','responsable_bogie','RESPONSABLE :','texto',1),('RESPONSABLES BOGIE','firma_responsable_bogie','FIRMA:','firma',2),('RESPONSABLES BOGIE','tecnico_turno_1','TÉCNICO ESPECIALISTA TURNO 1:','texto',3),('RESPONSABLES BOGIE','firma_tecnico_turno_1','FIRMA:','firma',4),('RESPONSABLES BOGIE','tecnico_turno_2','TÉCNICO ESPECIALISTA TURNO 2:','texto',5),('RESPONSABLES BOGIE','firma_tecnico_turno_2','FIRMA:','firma',6),('RESPONSABLES CAJA REDUCTORA','responsable_mantenimiento','RESPONSABLE MANTENIMIENTO :','texto',1),('RESPONSABLES CAJA REDUCTORA','firma_responsable_mantenimiento','FIRMA:','firma',2),('RESPONSABLES CAJA REDUCTORA','responsable_01','RESPONSABLE 01:','texto',3),('RESPONSABLES CAJA REDUCTORA','firma_responsable_01','FIRMA:','firma',4),('RESPONSABLES CAJA REDUCTORA','responsable_02','RESPONSABLE 02:','texto',5),('RESPONSABLES CAJA REDUCTORA','firma_responsable_02','FIRMA:','firma',6)) INSERT INTO cartillas.campos(seccion_id,codigo,etiqueta,tipo,orden,configuracion) SELECT s.id,d.codigo,d.etiqueta,d.tipo,d.orden,'{}'::jsonb FROM d JOIN s ON s.titulo=d.titulo ON CONFLICT(seccion_id,codigo) DO UPDATE SET activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
